#!/usr/bin/env bash
# Fixes a real diagnostic dead-end hit TWICE now in this deployment: the
# supervised kiosk-app process's stdout/stderr were piped straight to
# DEVNULL, so every time it crashed or exited unexpectedly (most recently:
# a clean exit(0) about 12 seconds after a successful start and passing
# health check, cause still unknown), there was no way to see why - only
# the fact that it happened.
#
# ProcessSupervisor now accepts a log_path and, when the process starts,
# redirects both stdout and stderr there (append mode, so a crash-loop's
# full history stays in one file across restarts) instead of discarding
# them. agent/main.py wires this to
# <data dir>/logs/kiosk-app.log — on Windows that's
# C:\ProgramData\OpsLabAgent\logs\kiosk-app.log. Falls back to DEVNULL
# (unchanged behavior) if the log file can't be opened for some reason,
# rather than failing to start the kiosk app entirely over a logging
# problem.
#
# Verified: a real subprocess's stdout AND stderr both land in the file;
# confirmed it appends (not truncates) across repeated restarts; confirmed
# an unconfigured supervisor with a log_path set is still a safe no-op.
#
# This does not fix the exit(0)-after-12s issue itself - it makes that
# issue actually diagnosable. Once this is deployed and Ewan hits it again,
# C:\ProgramData\OpsLabAgent\logs\kiosk-app.log will have the real
# answer.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> Extracting fixed agent/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'AGENT_TAR_EOF_MARKER'

AGENT_TAR_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "log_path" "$TMP_EXTRACT/agent/process_supervisor.py"; then
    echo "    ERROR: fix not found in the extracted agent payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
echo "    Updated agent/*.py in this repo."

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (served by /install.ps1)"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> Verifying"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    served agent tarball is readable"

echo ""
echo "Done. On Ewan, re-enroll once more to pick this up (same as the last two"
echo "agent-side fixes - there is nothing successfully installed yet for it to"
echo "self-update from):"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <fresh-token> -AdminUrl https://kiosksys.opslabsystems.cloud"
echo ""
echo "After it reaches the same exit(0)-after-12s point again, check:"
echo "    Get-Content \"C:\\ProgramData\\OpsLabAgent\\logs\\kiosk-app.log\" -Tail 50"
echo "That will have the kiosk app's actual stdout/stderr from the moment it"
echo "started to the moment it exited - the real answer, not another guess."
